SELECT 'tabla_c13' control,IF(COUNT(*)=1,0,1) errores FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='cont_regularizacion_evaluaciones' AND ENGINE='InnoDB';
SELECT 'triggers_c13' control,IF(COUNT(*)=2,0,1) errores FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('c13_evaluacion_no_update','c13_evaluacion_no_delete');
SELECT 'huerfanos_c13' control,COUNT(*) errores FROM cont_regularizacion_evaluaciones e LEFT JOIN cont_regularizacion_solicitudes s ON s.empresa_id=e.empresa_id AND s.entidad_id=e.entidad_id AND s.ejercicio_id=e.ejercicio_id AND s.id=e.solicitud_id WHERE s.id IS NULL;
SELECT 'continuidad_c13' control,COUNT(*) errores FROM (SELECT empresa_id,entidad_id,ejercicio_id,solicitud_id FROM cont_regularizacion_evaluaciones GROUP BY empresa_id,entidad_id,ejercicio_id,solicitud_id HAVING MIN(version)<>1 OR MAX(version)<>COUNT(*)) c;
SELECT 'contrato_c13' control,COUNT(*) errores FROM cont_regularizacion_evaluaciones WHERE NOT JSON_VALID(registro_json) OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(registro_json,'$.contrato')),'')<>'C3C13-CONSTANCIA-1' OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(registro_json,'$.informe.estadoFormal')),'')<>'PENDIENTE' OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(registro_json,'$.informe.contabilizado')),'')<>'false' OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(registro_json,'$.informe.aprobacionFormalHabilitada')),'')<>'false';
